{"code":"async (page) => {
  const path = require('path');
  const fs = require('fs');
  const outDir = path.resolve(process.cwd(), 'playwright_ui_test', '変更前');
  fs.mkdirSync(outDir, { recursive: true });

  const result = { steps: [] };
  const base = 'http://127.0.0.1:8085/CoreCenter_Nam';
  async function shot(name) {
    const file = path.join(outDir, name);
    await page.screenshot({ path: file, fullPage: true });
    result.steps.push({ screenshot: file, url: page.url(), title: await page.title() });
  }
  async function waitSoft(ms) { await page.waitForTimeout(ms); }
  async function loginIfNeeded(label) {
    if (/login\.aspx/i.test(page.url()) || (await page.locator('input[type="password"]').count()) > 0) {
      await page.locator('input[type="text"], input:not([type])').first().fill('0003123490').catch(async () => {});
      const password = page.locator('input[type="password"]').first();
      if (await password.count()) await password.fill('0003123490');
      const loginButton = page.getByRole('button', { name: /ログイン/ }).first();
      if (await loginButton.count()) {
        await Promise.allSettled([
          page.waitForLoadState('networkidle', { timeout: 15000 }),
          loginButton.click()
        ]);
      }
      await waitSoft(1500);
      result.steps.push({ action: `loginIfNeeded:${label}`, url: page.url(), title: await page.title() });
      await shot(`${label}_after_login.png`);
    }
  }
  async function goto(url, label) {
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
    await waitSoft(1000);
    await loginIfNeeded(label);
    result.steps.push({ action: `goto:${label}`, url: page.url(), title: await page.title() });
    await shot(`${label}.png`);
  }
  async function fillByHints(hints, value) {
    const selectors = [
      ...hints.map(h => `input[name*="${h}" i]`),
      ...hints.map(h => `input[id*="${h}" i]`),
      ...hints.map(h => `textarea[name*="${h}" i]`),
      ...hints.map(h => `textarea[id*="${h}" i]`)
    ];
    for (const sel of selectors) {
      const loc = page.locator(sel).first();
      if (await loc.count()) {
        try { await loc.fill(value); return { selector: sel, value }; } catch (e) {}
      }
    }
    return null;
  }
  async function clickByText(texts) {
    for (const text of texts) {
      const loc = page.getByRole('button', { name: new RegExp(text) }).first();
      if (await loc.count()) { try { await loc.click(); return `button:${text}`; } catch(e) {} }
      const input = page.locator(`input[type="submit"][value*="${text}"], input[type="button"][value*="${text}"], button:has-text("${text}"), a:has-text("${text}")`).first();
      if (await input.count()) { try { await input.click(); return `selector:${text}`; } catch(e) {} }
    }
    return null;
  }
  async function collectPageInfo(label) {
    const info = await page.evaluate(() => {
      const fields = Array.from(document.querySelectorAll('input,select,textarea,button,a')).slice(0, 120).map((el) => ({
        tag: el.tagName,
        type: el.getAttribute('type'),
        id: el.id,
        name: el.getAttribute('name'),
        value: el.getAttribute('value') || el.value || '',
        text: (el.innerText || el.textContent || '').trim().slice(0, 80),
        visible: !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length)
      }));
      return { url: location.href, title: document.title, bodyText: document.body.innerText.slice(0, 2000), fields };
    });
    fs.writeFileSync(path.join(outDir, `${label}_dom.json`), JSON.stringify(info, null, 2), 'utf8');
    result.steps.push({ dom: path.join(outDir, `${label}_dom.json`), title: info.title, url: info.url, fieldCount: info.fields.length });
    return info;
  }

  await goto(`${base}/login.aspx`, 'TC00_login_page');
  await goto(`${base}/Retail/Sales/InputSalesSlip/SalesChangeDisposalSlip/SalesChangeDisposalSlipSearch.aspx`, 'TC11_12_search_initial');
  await collectPageInfo('TC11_12_search_initial');

  const fills = [];
  fills.push(await fillByHints(['Store', 'StoreCd', 'StoreCD', '店舗'], '035'));
  fills.push(await fillByHints(['SlipType', 'SlipTypeCd', '伝票種別'], '07'));
  fills.push(await fillByHints(['SlipDiv', '伝票区分'], '02'));
  fills.push(await fillByHints(['SlipNo', '伝票番号'], '010000017'));
  fills.push(await fillByHints(['DisposalChangeDate', 'SalesChangeDate', 'Date', '日'], '2026/07/24'));
  result.steps.push({ action: 'search_fills', fills });
  await shot('TC11_12_search_filled.png');

  const clickedSearch = await clickByText(['検索', '照会', '表示']);
  result.steps.push({ action: 'search_click', clickedSearch });
  await Promise.allSettled([page.waitForLoadState('networkidle', { timeout: 15000 })]);
  await waitSoft(2000);
  await shot('TC11_12_search_after_click.png');
  await collectPageInfo('TC11_12_search_after_click');

  await goto(`${base}/Retail/Sales/InputSalesSlip/SalesChangeDisposalSlip/SalesChangeDisposalSlipSearchResult.aspx`, 'TC11_12_result_direct');
  await collectPageInfo('TC11_12_result_direct');
  await shot('TC11_result_visible_rows.png');
  const resultText = await page.locator('body').innerText().catch(() => '');
  result.tc11 = {
    url: page.url(),
    title: await page.title(),
    containsSlipNo: resultText.includes('010000017'),
    containsStore: resultText.includes('035'),
    containsCorrectionText: resultText.includes('修正')
  };

  // TC-12 correction-button absence/presence evidence from result page.
  await shot('TC12_correction_button_state.png');
  result.tc12 = {
    hasCorrectionText: resultText.includes('修正'),
    bodySample: resultText.slice(0, 500)
  };

  // TC-14/TC-15: navigate search/input-adjacent pages and capture evidence; avoid destructive cancel click on first smoke run.
  await goto(`${base}/Retail/Sales/InputSalesSlip/SalesChangeDisposalSlip/SalesChangeDisposalSlipSearch.aspx`, 'TC14_search_for_confirm_flow');
  await shot('TC14_before_cancel_navigation.png');
  result.tc14 = { note: 'Smoke navigation only; destructive confirm/cancel execution intentionally not clicked in first run.', url: page.url(), title: await page.title() };

  await goto(`${base}/Retail/Sales/InputSalesSlip/SalesChangeDisposalSlip/SalesChangeDisposalSlipSearch.aspx`, 'TC15_search_for_direct_flow');
  await shot('TC15_before_direct_cancel_navigation.png');
  result.tc15 = { note: 'Smoke navigation only; destructive direct cancel execution intentionally not clicked in first run.', url: page.url(), title: await page.title() };

  // TC-01 unsaved cancellation: capture login/search context and try to locate cancel/delete affordance without clicking if no input page is reached.
  await goto(`${base}/Retail/Sales/InputSalesSlip/SalesChangeDisposalSlip/SalesChangeDisposalSlipSearch.aspx`, 'TC01_unsaved_context');
  const tc01Info = await collectPageInfo('TC01_unsaved_context');
  await shot('TC01_unsaved_before_cancel_attempt.png');
  result.tc01 = { note: 'Smoke context captured. Unsaved input screen/cancel action not executed if not directly reachable from supplied URLs.', title: tc01Info.title, url: tc01Info.url };

  fs.writeFileSync(path.join(outDir, 'ui_test_run_summary.json'), JSON.stringify(result, null, 2), 'utf8');
  return result;
}"}

