9:
10:namespace NihonUnisys.CoreCenter.Retail.Sales.InputSalesSlip.Business.SlipHeaderListDataSetTableAdapters
11:{
12:    #region DAOCSAR05003
13:    /// <summary>
14:    /// 伝票ヘッダ一覧情報に関するテーブルアダプター。
15:    /// 売変廃棄伝票検索画面にて使用している。
16:    /// </summary>
17:    [System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Naming", "CA1709:IdentifiersShouldBeCasedCorrectly", MessageId = "CMC")]
18:    public partial class SlipHeaderListDataTableAdapter
19:    {
20:        /// <summary>
21:        /// テーブルアダプターの初期化処理を行います。
22:        /// </summary>
23:        public override void Initialize()
24:        {
25:            this.QueryOverwrite(this.CommandCollection);
26:        }
27:
28:        /// <summary>
29:        /// 検索条件を元に動的クエリを発行し、対象データ(ＣＭＣ店舗グループ１)を取得します。
30:        /// </summary>
31:        /// <param name="slipHeaderListSearchConditionEntity">伝票ヘッダ検索条件Ent</param>
32:        /// <param name="slipTypeSearchConditionEntity">伝票種別検索条件Ent</param>
33:        /// <param name="slipHeaderListDataSet">伝票ヘッダ一覧情報Ds</param>
34:        /// <returns>取得件数</returns>
35:        public int FillBySlipHeaderListSearchCondition(
36:            SlipHeaderListSearchConditionEntity slipHeaderListSearchConditionEntity,
37:            SlipTypeSearchConditionEntity slipTypeSearchConditionEntity,
38:            SlipHeaderListDataSet slipHeaderListDataSet)
39:        {
40:            // コマンドの作成(Command)
41:            using (DbCommand dbCommand = this.Connection.CreateCommand())
42:            {
43:                // コネクションの作成(Connection)
44:                // ただし、今回は自動生成で作られたConnectionを再利用する。
45:                dbCommand.Connection = this.Connection;
46:                dbCommand.CommandText = this.CreateFillQuery(
47:                    slipHeaderListSearchConditionEntity,
48:                    slipTypeSearchConditionEntity);
49:
50:                // アダプターの作成(Adapter)
51:                // アダプターにコマンドをセットしてあげる。
52:                this.Adapter.SelectCommand = (SqlCommand)dbCommand;
53:
54:                // Fillをする前に、対象のデータテーブルのデータをクリアするか、否かをチェックする
55:                if (ClearBeforeFill)
56:                {
57:                    slipHeaderListDataSet.SlipHeaderListDataTable.Clear();
58:                }
59:
60:                // Fillメソッドを呼び出す。
61:                // Fillメソッドは取得件数を戻り値で返してくれる
62:                return this.Adapter.Fill(slipHeaderListDataSet.SlipHeaderListDataTable);
63:            }
64:        }
65:
66:        /// <summary>
67:        /// 検索するためのクエリを作成します。
68:        /// </summary>
69:        /// <param name="slipHeaderListSearchConditionEntity">伝票ヘッダ検索条件Ent</param>
70:        /// <param name="slipTypeSearchConditionEntity">伝票種別検索条件Ent</param>
71:        /// <returns>クエリ</returns>
72:        private string CreateFillQuery(
73:            SlipHeaderListSearchConditionEntity slipHeaderListSearchConditionEntity,
74:            SlipTypeSearchConditionEntity slipTypeSearchConditionEntity)
75:        {
76:            // 引数の表示順検索条件EntityからSQLを動的に組み立てる。DbParameter が使える場合は極力使用する。
77:            StringBuilder sqlBuilder = new StringBuilder();
78:
79:            if (string.IsNullOrEmpty(slipHeaderListSearchConditionEntity.ErrorDiv))
80:            {
81:                slipHeaderListSearchConditionEntity.ErrorDiv = string.Empty;
82:            }
83:
84:            // ◇伝票ヘッダ検索条件Ent.ErrorDiv <> '2' である場合  ※全件、正常、警告を検索の場合  
85:            if (!slipHeaderListSearchConditionEntity.ErrorDiv.Equals("2"))
86:            {
87:                sqlBuilder.Append(" SELECT DISTINCT ");
88:                sqlBuilder.Append("  HD.DisposalChangeDate ");
89:                sqlBuilder.Append(" ,HD.SlipTypeCd ");
90:                sqlBuilder.Append(" ,'' AS SlipTypeName ");
91:                sqlBuilder.Append(" ,HD.SlipDiv ");
92:                sqlBuilder.Append(" ,'' AS SlipDivName ");
93:                sqlBuilder.Append(" ,HD.SlipNo ");
94:                sqlBuilder.Append(" ,HD.StoreCd ");
95:                sqlBuilder.Append(" ,HD.Category1Cd ");
96:                sqlBuilder.Append(" ,HD.Category2Cd ");
97:                sqlBuilder.Append(" ,HD.TotalQty ");
98:                sqlBuilder.Append(" ,HD.SlipOldTotalPrice ");
99:                sqlBuilder.Append(" ,HD.SlipNewTotalPrice ");
100:                sqlBuilder.Append(" ,HD.AutoSalesChangeFlg ");
101:                sqlBuilder.Append(" ,HD.PostingDate ");
102:                sqlBuilder.Append(" ,HD.SlipTotalDisposalAmt ");
103:                sqlBuilder.Append(" ,HD.InputBatchNo ");
104:                sqlBuilder.Append(" ,HD.ApprovalStatus ");
105:                sqlBuilder.Append(" ,HD.CorporationCode ");
106:                sqlBuilder.Append(" ,HD.SlipBranchNo ");
107:                sqlBuilder.Append(" ,HD.InputMediaDiv ");
108:                sqlBuilder.Append(" ,HD.InputBatchNo ");
109:                sqlBuilder.Append(" ,HD.InputSequenceNo ");
110:#warning SKN臨時対応
111:                //sqlBuilder.Append(" ,NULL AS InputDate ");
112:                sqlBuilder.Append(" ,'' AS InputDate ");
113:                sqlBuilder.Append(" ,'' AS InputTime ");
114:                sqlBuilder.Append(" ,'' AS DateType ");
115:                sqlBuilder.Append(" ,CASE WHEN HD.SlipRevisionFlg <> '1' ");
116:                sqlBuilder.Append(" THEN '1' ");
117:                sqlBuilder.Append(" ELSE '0' ");
118:                sqlBuilder.Append(" END AS SlipCorrectionAvailabilityFlg ");
119:                sqlBuilder.Append(" ,'2' AS CorrectionTable ");
120:                sqlBuilder.Append(" FROM SARSlipHeader HD ");
121:
122:                // ◇伝票ヘッダ検索条件Ent.エラー区分　＝　'1' である場合　　※警告を検索 
123:                if (slipHeaderListSearchConditionEntity.ErrorDiv.Equals("1"))
124:                {
125:                    sqlBuilder.Append(" INNER JOIN SARSlipHeaderError HDERR ");
126:                    sqlBuilder.Append(" ON HD.CorporationCode = HDERR.CorporationCode ");
127:                    sqlBuilder.Append(" AND HD.InputMediaDiv = HDERR.InputMediaDiv ");
128:                    sqlBuilder.Append(" AND HD.InputBatchNo = HDERR.InputBatchNo ");
129:                    sqlBuilder.Append(" AND HD.InputSequenceNo = HDERR.InputSequenceNo ");
130:                    sqlBuilder.Append(" AND HD.SlipDiv = HDERR.SlipDiv ");
--- 130-240
130:                    sqlBuilder.Append(" AND HD.SlipDiv = HDERR.SlipDiv ");
131:                    sqlBuilder.Append(" AND HD.SlipTypeCd = HDERR.SlipTypeCd ");
132:                    sqlBuilder.Append(" AND HD.SlipNo = HDERR.SlipNo ");
133:
134:                    // sqlBuilder.Append(" AND HD.SlipBranchNo = HDERR.SlipBranchNo ");
135:                    sqlBuilder.Append(" AND HD.StoreCd = HDERR.StoreCd ");
136:                    sqlBuilder.Append(" AND HDERR.ErrorDiv = '1' ");
137:                    sqlBuilder.Append(" AND HDERR.FixDate IS NOT NULL ");
138:                }
